const application=document.querySelector('#applicationForm');
if(application){const panels=[...application.querySelectorAll('[data-step]')],progress=[...document.querySelectorAll('.application-progress li')];let current=1;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());application.elements.birthDate.max=today;application.elements.diagnosisDate.max=today;
const showStep=n=>{current=n;panels.forEach((panel,i)=>{panel.hidden=i+1!==n;if(panel.tagName==='FIELDSET')panel.disabled=i+1!==n});progress.forEach((li,i)=>{li.classList.toggle('complete',i+1<n);if(i+1===n)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current')});const heading=panels[n-1].querySelector('legend,h2');heading.tabIndex=-1;heading.focus({preventScroll:true});document.querySelector('.application-progress').scrollIntoView({behavior:'smooth',block:'start'})};
const validate=()=>{const birth=application.elements.birthDate,diagnosis=application.elements.diagnosisDate;diagnosis.setCustomValidity(diagnosis.value&&birth.value&&diagnosis.value<birth.value?'La fecha de diagnóstico no puede ser anterior al nacimiento.':'');for(const field of panels[current-1].querySelectorAll('input,select'))if(!field.reportValidity())return false;return true};
application.querySelector('[data-step="1"] .next-step').addEventListener('click',()=>{if(validate()){application.elements.medicalGender.value=application.elements.gender.value;showStep(2)}});application.querySelector('.previous-step').addEventListener('click',()=>showStep(1));
application.querySelectorAll('input[type="file"]').forEach(input=>input.addEventListener('change',()=>{const file=input.files[0],status=document.getElementById(input.dataset.fileStatus);input.setCustomValidity('');if(!file){status.textContent='Sin archivo seleccionado';return}if(!/\.(pdf|jpe?g|png)$/i.test(file.name)||file.size>20*1024*1024){input.value='';input.setCustomValidity('Selecciona un PDF, JPG o PNG de hasta 20 MB.');status.textContent='Archivo no válido: PDF, JPG o PNG, máximo 20 MB.';input.reportValidity();return}status.textContent=file.name}));
application.addEventListener('submit',e=>{e.preventDefault();if(current!==2||!validate())return;document.querySelector('#applicationFolio').textContent='DEMO-EC-'+crypto.getRandomValues(new Uint32Array(1))[0].toString(16).toUpperCase().padStart(8,'0');document.querySelector('#applicationDate').textContent=new Intl.DateTimeFormat('es-MX',{timeZone:'America/Mexico_City'}).format(new Date());document.querySelector('#applicationEmail').textContent=application.elements.email.value;showStep(3)});
document.querySelector('#restartApplication').addEventListener('click',()=>{application.reset();application.querySelectorAll('input').forEach(i=>i.setCustomValidity(''));application.querySelectorAll('[data-file-status]').forEach(i=>document.getElementById(i.dataset.fileStatus).textContent='Sin archivo seleccionado');showStep(1)})}
